  "inlineSchema": "// ─────────────────────────────────────────────────────────────\n// BANCO DA APLICAÇÃO (leitura e escrita): usuários, sessões\n// (refresh tokens) e auditoria. Conexão: APP_DATABASE_URL.\n//\n// O banco do Voalle NÃO passa pelo Prisma: é acessado somente\n// para leitura via pg parametrizado em\n// src/repositories/voalle.repository.ts (VOALLE_DB_*).\n// ─────────────────────────────────────────────────────────────\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum UserRole {\n  ADMIN\n  OPERATOR\n  TECHNICIAN\n  VIEWER\n}\n\nmodel User {\n  id           String    @id @default(uuid()) @db.Uuid\n  name         String\n  /// Sempre armazenado normalizado em minúsculas; unicidade case-insensitive.\n  email        String    @unique\n  passwordHash String\n  role         UserRole\n  active       Boolean   @default(true)\n  lastLoginAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n  createdBy    String?   @db.Uuid\n  updatedBy    String?   @db.Uuid\n\n  refreshTokens RefreshToken[]\n  auditLogs     AuditLog[]\n\n  viabilityConsultations  ViabilityConsultation[] @relation(\"ViabilityConsultationUser\")\n  coveragePartnersCreated CoveragePartner[]       @relation(\"CoveragePartnerCreatedBy\")\n  coveragePartnersUpdated CoveragePartner[]       @relation(\"CoveragePartnerUpdatedBy\")\n  coverageLayersUploaded  CoverageLayer[]         @relation(\"CoverageLayerUploadedBy\")\n\n  @@map(\"users\")\n}\n\n/// Sessões de renovação: guarda SOMENTE o hash SHA-256 do token, nunca o\n/// token puro. familyId permite revogar a cadeia inteira ao detectar reuso.\nmodel RefreshToken {\n  id            String    @id @default(uuid()) @db.Uuid\n  userId        String    @db.Uuid\n  user          User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash     String    @unique\n  familyId      String    @db.Uuid\n  expiresAt     DateTime\n  createdAt     DateTime  @default(now())\n  revokedAt     DateTime?\n  /// ROTATED = consumido por renovacao (janela de graca de corrida se aplica);\n  /// SECURITY = revogado por logout, inativacao, troca/reset de senha ou reuso.\n  revokedReason String?\n\n  @@index([userId])\n  @@index([familyId])\n  @@map(\"refresh_tokens\")\n}\n\n/// Auditoria: nunca guarda senhas, hashes, tokens, chaves, credenciais do\n/// Voalle ou o conteúdo completo de endereços consultados.\nmodel AuditLog {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String?  @db.Uuid\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  action    String\n  entity    String\n  entityId  String?\n  metadata  Json?\n  ipAddress String?\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([action])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\nenum CoverageFileType {\n  KML\n  KMZ\n}\n\nenum CoverageProcessingStatus {\n  PENDING\n  PROCESSING\n  READY\n  FAILED\n}\n\n/// Parceiro/rede dona de camadas de cobertura (v0.3.0).\nmodel CoveragePartner {\n  id          String   @id @default(uuid()) @db.Uuid\n  name        String\n  code        String   @unique\n  description String?\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  createdById String?  @db.Uuid\n  updatedById String?  @db.Uuid\n\n  createdBy User? @relation(\"CoveragePartnerCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User? @relation(\"CoveragePartnerUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  layers CoverageLayer[]\n\n  @@map(\"coverage_partners\")\n}\n\n/// Arquivo KML/KMZ importado de um parceiro. O binario fica em disco\n/// (COVERAGE_STORAGE_PATH) — NUNCA como blob no banco. storedFileName e\n/// interno e jamais exposto pela API.\nmodel CoverageLayer {\n  id                   String                   @id @default(uuid()) @db.Uuid\n  partnerId            String                   @db.Uuid\n  partner              CoveragePartner          @relation(fields: [partnerId], references: [id], onDelete: Cascade)\n  name                 String\n  description          String?\n  version              String?\n  originalFileName     String\n  storedFileName       String                   @unique\n  fileType             CoverageFileType\n  fileSize             Int\n  sha256               String                   @unique\n  active               Boolean                  @default(true)\n  processingStatus     CoverageProcessingStatus @default(PENDING)\n  polygonCount         Int                      @default(0)\n  areaCount            Int                      @default(0)\n  ignoredGeometryCount Int                      @default(0)\n  processingError      String?\n  uploadedById         String?                  @db.Uuid\n  uploadedBy           User?                    @relation(\"CoverageLayerUploadedBy\", fields: [uploadedById], references: [id], onDelete: SetNull)\n  createdAt            DateTime                 @default(now())\n  updatedAt            DateTime                 @updatedAt\n\n  @@index([partnerId])\n  @@index([active, processingStatus])\n  @@map(\"coverage_layers\")\n}\n\n/// Historico IMUTAVEL das consultas de viabilidade (v0.4.0). Cada registro\n/// e um snapshot do resultado apresentado no momento da consulta — mudancas\n/// posteriores nas camadas/parceiros NAO alteram consultas antigas. Nunca\n/// armazena credenciais, tokens, respostas brutas do Google, stack traces,\n/// storedFileName nem poligonos.\nmodel ViabilityConsultation {\n  id            String    @id @default(uuid()) @db.Uuid\n  protocol      String    @unique\n  userId        String?   @db.Uuid\n  user          User?     @relation(\"ViabilityConsultationUser\", fields: [userId], references: [id], onDelete: SetNull)\n  status        String\n  resultMessage String\n  createdAt     DateTime  @default(now())\n  completedAt   DateTime?\n  durationMs    Int?\n\n  // Endereco informado pelo operador\n  postalCode   String?\n  street       String\n  number       String\n  complement   String?\n  neighborhood String?\n  city         String\n  state        String\n\n  // Geocodificacao (somente dados publicos ja expostos pela consulta)\n  geocodingProvider     String\n  geocodedAddress       String?\n  geocodingConfidence   String?\n  geocodingLocationType String?\n  geocodingPartialMatch Boolean @default(false)\n  geocodedLatitude      Float?\n  geocodedLongitude     Float?\n\n  // Confirmacao manual no mapa\n  confirmedLatitude         Float?\n  confirmedLongitude        Float?\n  locationConfirmedManually Boolean @default(false)\n  confirmationRequired      Boolean @default(false)\n\n  // Snapshot da cobertura no momento da consulta\n  coverageMatches         Json\n  coverageMatchCount      Int       @default(0)\n  coverageConfigured      Boolean   @default(false)\n  coverageSnapshotBuiltAt DateTime?\n\n  // Referencia de rede (Voalle) — somente dados publicos permitidos\n  networkReferenceStatus    String\n  networkReference          Json?\n  networkAlternatives       Json\n  networkSearchRadiusMeters Int?\n\n  // Metadados seguros\n  requestId String?\n  source    String?\n  errorCode String?\n\n  @@index([createdAt])\n  @@index([userId])\n  @@index([status])\n  @@index([postalCode])\n  @@index([city])\n  @@index([state])\n  @@index([networkReferenceStatus])\n  @@map(\"viability_consultations\")\n}\n",
